      "mainEntity": [
        {
          "@type": "Question",
          "name": "Was West Baltimore redlined?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. On the federal Home Owners' Loan Corporation's 1937 map of Baltimore, most of the land in the nine tracts in this post was graded D, the lowest grade, shaded red. One tract, in Harlem Park, was graded C."
          }
        },
        {
          "@type": "Question",
          "name": "What is Baltimore's Highway to Nowhere?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "It is a sunken stretch of U.S. Route 40 in West Baltimore, built as the Franklin-Mulberry expressway. The city says 971 homes, 62 businesses and one school were torn down for it. It opened in 1979 but was never connected to I-70."
          }
        },
        {
          "@type": "Question",
          "name": "Why did the Sandtown-Winchester rebuilding effort fall short?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Reviews of the effort point to several reasons. It had no plan for jobs, most of the money went to houses, the 2008 housing crash hit the neighborhood hard, and the schools did not improve. One study found no effect on the neighborhood's poverty rate over the long run."
          }
        },
        {
          "@type": "Question",
          "name": "How many people live in West Baltimore?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "The nine census tracts in this post held about 85,500 people in 1950 and about 18,900 in 2020-2024, 78% fewer."
          }
        }
      ]
